ICON_LABELS = {
    "analysis": "Analysis",
    "gear": "Settings",
    "work_experience": "Work Experience",
    "date_format": "Date format",
    "person": "User",
    "user_role": "Role",
    "small_toggle": "Toggle pane",
    "pane_menu": "Pane menu",
    "paste": "Paste", "iterate": "Iterate", "arrow_up": "Arrow Up",
    "arrow_down": "Arrow Down", "toggle": "Toggle", "cycle": "Cycle",
    "selection": "Selection", "brief": "Brief", "linkedin": "LinkedIn",
    "github": "GitHub", "portfolio": "Portfolio", "facebook": "Facebook", "x": "X",
}


def infer_icon_names(action: str, display: dict) -> list[str]:
    selected = [str(icon) for icon in display.get("icons", []) if str(icon) in ICON_SVGS]
    if selected:
        return selected[:2]
    if not display.get("svg"):
        return []
    name = action.casefold()
    if "brief" in name:
        return ["brief"]
    if "cycle" in name:
        return ["cycle"]
    for social in ("linkedin", "github", "portfolio", "facebook", "x"):
        if name == social or social in name:
            return ["paste", social]
    if "previous" in name or "up" in name:
        return ["iterate", "arrow_up"]
    if "next" in name or "down" in name:
        return ["iterate", "arrow_down"]
    if "toggle" in name or "cycle" in name:
        return ["toggle"]
    if "iterate" in name or "sequence" in name:
        return ["iterate", "paste"]
    return ["paste"]
